insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000001',
  'b1000000-0000-4000-8000-000000000001',
  'present-simple-form',
  'Form',
  'Build habits and facts. Cue: every / usually / still.',
  'A2',
  '{"usage":"Goal: report routines, owners, and stable facts — not live WIP.","forms":{"affirmative":"I/you/we/they + V · he/she/it + V-s/es","negative":"don''t / doesn''t + base verb","question":"Do / Does + subject + base verb?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I ship small fixes every morning."},{"id":"ex-2","context":"Docs","sentence":"This service retries failed jobs."},{"id":"ex-3","context":"On-call","sentence":"She owns the payment webhook."},{"id":"ex-4","context":"PR","sentence":"We review pull requests on Fridays."},{"id":"ex-5","context":"Slack","sentence":"Nightly backups finish before dawn."}],"tips":["he/she/it takes -s; don''t/doesn''t + base (not doesn''t goes).","WIP in this standup uses Present Continuous, not Simple."]}'::jsonb,
  1,
  1,
  1,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000002',
  'b1000000-0000-4000-8000-000000000001',
  'present-simple-use',
  'Use',
  'Simple = habit/fact. Continuous = live now.',
  'B1',
  '{"usage":"Goal: pick Simple vs Continuous from cues (every / usually vs right now).","forms":{"affirmative":"I/you/we/they + V · he/she/it + V-s/es","negative":"don''t / doesn''t + base verb","question":"Do / Does + subject + base verb?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"She reviews pull requests every Friday."},{"id":"ex-2","context":"Slack","sentence":"I am shipping this hotfix now."},{"id":"ex-3","context":"Docs","sentence":"The gateway rejects unsigned tokens."},{"id":"ex-4","context":"Standup","sentence":"The weekly retro starts at 16:00."},{"id":"ex-5","context":"PR","sentence":"He owns the billing pipeline."}],"tips":["A schedule or owner stays Simple even if you mention today.","Do not use Simple for a ticket you are working this standup."]}'::jsonb,
  1,
  1,
  2,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000003',
  'b1000000-0000-4000-8000-000000000001',
  'present-simple-apply',
  'Apply',
  'Policy, SLA, and stative verbs stay Simple.',
  'B2',
  '{"usage":"Goal: keep contracts, SLAs, and statives (own, need, mean) in Simple.","forms":{"affirmative":"I/you/we/they + V · he/she/it + V-s/es","negative":"don''t / doesn''t + base verb","question":"Do / Does + subject + base verb?"},"examples":[{"id":"ex-1","context":"RFC","sentence":"This change requires a dual-write window."},{"id":"ex-2","context":"Policy","sentence":"Production deploys need two approvals."},{"id":"ex-3","context":"RFC","sentence":"The worker owns the outbox table."},{"id":"ex-4","context":"Slack","sentence":"The API returns 409 on duplicate keys."},{"id":"ex-5","context":"PR","sentence":"It means the cache is the source of truth."}],"tips":["Never mark is owning / is needing / is meaning as correct.","Written policy uses Simple, not a live Continuous snapshot."]}'::jsonb,
  1,
  1,
  3,
  true
)
