  'Form',
  'am/is/are + V-ing for work happening now.',
  'A2',
  '{"usage":"Goal: say what is in progress in this standup or incident.","forms":{"affirmative":"am / is / are + V-ing","negative":"am not / isn''t / aren''t + V-ing","question":"Am / Is / Are + subject + V-ing?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I am debugging the auth timeout."},{"id":"ex-2","context":"Slack","sentence":"We are rolling back the bad deploy."},{"id":"ex-3","context":"PR","sentence":"She is reviewing the migration now."},{"id":"ex-4","context":"On-call","sentence":"The worker is retrying failed jobs."},{"id":"ex-5","context":"Standup","sentence":"They aren''t merging until tests pass."}],"tips":["Use be + V-ing, not I debugging.","Statives (own, know, need) stay Simple."]}'::jsonb,
