insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000005',
  'b1000000-0000-4000-8000-000000000002',
  'present-continuous-use',
  'Use',
  'Now / at the moment vs habits and owners.',
  'B1',
  '{"usage":"Goal: use Continuous for this-cycle WIP; keep owners and schedules Simple.","forms":{"affirmative":"am / is / are + V-ing","negative":"am not / isn''t / aren''t + V-ing","question":"Am / Is / Are + subject + V-ing?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I am pairing on the flaky test right now."},{"id":"ex-2","context":"Slack","sentence":"At the moment we are seeing 5xx on checkout."},{"id":"ex-3","context":"Docs","sentence":"She owns the checkout service."},{"id":"ex-4","context":"Standup","sentence":"I usually handle alerts, but I am shadowing today."},{"id":"ex-5","context":"PR","sentence":"He is rewriting the retry loop this morning."}],"tips":["right now / at the moment / this morning (WIP) → Continuous.","usually / owns / every → Simple."]}'::jsonb,
  1,
  1,
  2,
  true
)
