  'A2',
  '{"usage":"Goal: report finished work with a finished time.","forms":{"affirmative":"subject + V-ed / irregular past","negative":"didn''t + base verb","question":"Did + subject + base verb?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I merged the hotfix yesterday."},{"id":"ex-2","context":"Slack","sentence":"We rolled back at 14:10."},{"id":"ex-3","context":"PR","sentence":"She closed the duplicate ticket."},{"id":"ex-4","context":"On-call","sentence":"They didn''t page secondary."},{"id":"ex-5","context":"Standup","sentence":"Did you ship the flag change?"}],"tips":["didn''t + base (not didn''t merged).","Finished clock time → Past Simple, not Present Perfect."]}'::jsonb,
  1,
  1,
  1,
  true
)
