insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000011',
  'b1000000-0000-4000-8000-000000000004',
  'past-continuous-use',
  'Use',
  'Background vs finished interrupt.',
  'B1',
  '{"usage":"Goal: Continuous for the scene; Simple for the event that cut in.","forms":{"affirmative":"was / were + V-ing","negative":"wasn''t / weren''t + V-ing","question":"Was / Were + subject + V-ing?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I was writing the RFC when Slack lit up."},{"id":"ex-2","context":"Slack","sentence":"While we were failing over, checkout stayed up."},{"id":"ex-3","context":"PR","sentence":"He merged after we were already rolling back."},{"id":"ex-4","context":"On-call","sentence":"The job was retrying when the lock expired."},{"id":"ex-5","context":"Standup","sentence":"I finished the notes after the call ended."}],"tips":["when/while + Continuous = background.","The interrupting event is usually Past Simple."]}'::jsonb,
  1,
  1,
  2,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
