insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000012',
  'b1000000-0000-4000-8000-000000000004',
  'past-continuous-apply',
  'Apply',
  'Incident narrative: what was running when impact started.',
  'B2',
  '{"usage":"Goal: set the scene of an incident without mixing Perfect clocks.","forms":{"affirmative":"was / were + V-ing","negative":"wasn''t / weren''t + V-ing","question":"Was / Were + subject + V-ing?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"We were draining connections when the proxy restarted."},{"id":"ex-2","context":"On-call","sentence":"Customers were checking out while we failed over."},{"id":"ex-3","context":"PR","sentence":"I was not changing prod config during that window."},{"id":"ex-4","context":"Standup","sentence":"The canary was soaking when error rate jumped."},{"id":"ex-5","context":"RFC","sentence":"Two writers were active when the unique index landed."}],"tips":["Use Continuous for overlapping work, Simple for the trigger.","Do not stamp was + V-ing with already/yet."]}'::jsonb,
  1,
  1,
  3,
  true
)
