  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000013',
  'b1000000-0000-4000-8000-000000000005',
  'present-perfect-form',
  'Form',
  'have/has + past participle. Cue: already / yet / so far.',
  'A2',
  '{"usage":"Goal: report an open result without a finished clock stamp.","forms":{"affirmative":"have / has + past participle","negative":"haven''t / hasn''t + past participle","question":"Have / Has + subject + past participle?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I have merged the hotfix."},{"id":"ex-2","context":"Slack","sentence":"We have not seen new 5xx yet."},{"id":"ex-3","context":"PR","sentence":"She has already updated the runbook."},{"id":"ex-4","context":"On-call","sentence":"Have you paged secondary yet?"},{"id":"ex-5","context":"Standup","sentence":"So far we have recovered checkout."}],"tips":["have/has + participle, not have + yesterday.","yet usually sits in negatives and questions."]}'::jsonb,
  1,
  1,
  1,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
