insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000014',
  'b1000000-0000-4000-8000-000000000005',
  'present-perfect-use',
  'Use',
  'Perfect result vs Past Simple stamp.',
  'B1',
  '{"usage":"Goal: already/yet/since/so far → Perfect; yesterday/at 14:00 → Past Simple.","forms":{"affirmative":"have / has + past participle","negative":"haven''t / hasn''t + past participle","question":"Have / Has + subject + past participle?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I have already shipped the flag."},{"id":"ex-2","context":"Slack","sentence":"We rolled back at 14:10."},{"id":"ex-3","context":"PR","sentence":"She has not approved the RFC yet."},{"id":"ex-4","context":"On-call","sentence":"Errors have dropped since the revert."},{"id":"ex-5","context":"Standup","sentence":"I finished the notes yesterday."}],"tips":["since + starting point keeps Present Perfect.","A clock time in the same clause usually forces Past Simple."]}'::jsonb,
  1,
  1,
  2,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
