  'Status that is still true for clients and tickets.',
  'B2',
  '{"usage":"Goal: give current status with Perfect; stamp history with Simple.","forms":{"affirmative":"have / has + past participle","negative":"haven''t / hasn''t + past participle","question":"Have / Has + subject + past participle?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"We have restored checkout; monitoring is still open."},{"id":"ex-2","context":"Client","sentence":"We have not confirmed a root cause yet."},{"id":"ex-3","context":"PR","sentence":"I have added the missing index since the review."},{"id":"ex-4","context":"On-call","sentence":"Pages have stayed quiet for 40 minutes."},{"id":"ex-5","context":"Standup","sentence":"We closed the incident at 12:40."}],"tips":["Client updates prefer have/has for unfinished investigation.","Do not write have restored at 12:40 in one clause."]}'::jsonb,
