  'future-forms-form',
  'Form',
  'will + V and be going to + V.',
  'A2',
  '{"usage":"Goal: form decisions (will) and plans already decided (going to).","forms":{"affirmative":"will + V  ·  am/is/are going to + V","negative":"won''t + V  ·  am/is/are not going to + V","question":"Will + subject + V?  ·  Be + going to + V?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I will pair with you after this call."},{"id":"ex-2","context":"Slack","sentence":"We are going to roll forward at 18:00."},{"id":"ex-3","context":"PR","sentence":"She won''t merge until CI is green."},{"id":"ex-4","context":"Client","sentence":"We are going to share an ETA today."},{"id":"ex-5","context":"Standup","sentence":"Will you take the on-call swap?"}],"tips":["will + base, not will to / will merging.","going to + base, not going to + V-ing."]}'::jsonb,
  1,
  1,
  1,
  true
)
