values (
  'b2000000-0000-4000-8000-000000000017',
  'b1000000-0000-4000-8000-000000000006',
  'future-forms-use',
  'Use',
  'will = decision now; going to = plan already set.',
  'B1',
  '{"usage":"Goal: choose will for instant offers/decisions and going to for scheduled plans.","forms":{"affirmative":"will + V  ·  am/is/are going to + V","negative":"won''t + V  ·  am/is/are not going to + V","question":"Will + subject + V?  ·  Be + going to + V?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"Okay, I will revert the flag."},{"id":"ex-2","context":"Slack","sentence":"We are going to fail over at 21:00 as planned."},{"id":"ex-3","context":"PR","sentence":"I will address the comments this afternoon."},{"id":"ex-4","context":"Client","sentence":"We are going to send a written update by 16:00."},{"id":"ex-5","context":"Standup","sentence":"If CI stays red, we will slip the train."}],"tips":["Okay, I will... is a decision in the meeting.","as planned / at 21:00 on the calendar → going to."]}'::jsonb,
  1,
  1,
  2,
  true
)
