values (
  'b2000000-0000-4000-8000-000000000018',
  'b1000000-0000-4000-8000-000000000006',
  'future-forms-apply',
  'Apply',
  'Client promises vs internal plans.',
  'B2',
  '{"usage":"Goal: sound reliable: going to for committed plans, will for next-step decisions.","forms":{"affirmative":"will + V  ·  am/is/are going to + V","negative":"won''t + V  ·  am/is/are not going to + V","question":"Will + subject + V?  ·  Be + going to + V?"},"examples":[{"id":"ex-1","context":"Client","sentence":"We are going to keep the workaround until the patch lands."},{"id":"ex-2","context":"Slack","sentence":"I will ping you when the canary is clean."},{"id":"ex-3","context":"Standup","sentence":"We are not going to ship schema changes in this freeze."},{"id":"ex-4","context":"PR","sentence":"I will not merge until the migration has a rollback."},{"id":"ex-5","context":"Client","sentence":"We will confirm the new ETA after the next soak."}],"tips":["Do not promise will if the calendar already has a going-to plan.","will not / will not + base for refusals and gates."]}'::jsonb,
