values (
  'b2000000-0000-4000-8000-000000000019',
  'b1000000-0000-4000-8000-000000000007',
  'progress-earlier-past-form',
  'Form',
  'have been + V-ing and had + V-ed for earlier past.',
  'B1',
  '{"usage":"Goal: introduce duration up to now (have been) and the earlier of two pasts (had).","forms":{"affirmative":"have/has been + V-ing  ·  had + past participle","negative":"haven''t/hasn''t been + V-ing  ·  hadn''t + past participle","question":"Have/Has + subject + been + V-ing?  ·  Had + subject + V-ed?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I have been chasing the flaky test all morning."},{"id":"ex-2","context":"Slack","sentence":"We had already failed over before the page storm."},{"id":"ex-3","context":"PR","sentence":"She has been rewriting the retry loop since Monday."},{"id":"ex-4","context":"On-call","sentence":"The job had died before the lock expired."},{"id":"ex-5","context":"Standup","sentence":"Had you seen the 5xx before we reverted?"}],"tips":["have been + V-ing for unfinished duration; had + participle for earlier past.","These forms are optional — Core Tenses already cover daily status."]}'::jsonb,
  1,
  1,
  1,
  true
)
