insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000020',
  'b1000000-0000-4000-8000-000000000007',
  'progress-earlier-past-use',
  'Use',
  'Duration vs earlier cause in incident notes.',
  'B2',
  '{"usage":"Goal: have been for ongoing effort; had for the cause that happened first.","forms":{"affirmative":"have/has been + V-ing  ·  had + past participle","negative":"haven''t/hasn''t been + V-ing  ·  hadn''t + past participle","question":"Have/Has + subject + been + V-ing?  ·  Had + subject + V-ed?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"We have been soaking the canary for 40 minutes."},{"id":"ex-2","context":"On-call","sentence":"The cache had gone stale before checkout failed."},{"id":"ex-3","context":"Standup","sentence":"I have been blocked on access since standup."},{"id":"ex-4","context":"PR","sentence":"He had opened the RFC before we found the lock."},{"id":"ex-5","context":"Client","sentence":"We had not reproduced it until this morning."}],"tips":["If both events are finished, the earlier one often takes had.","Do not use had when the result is still true now — use have/has."]}'::jsonb,
  1,
  1,
  2,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
