values (
  'b2000000-0000-4000-8000-000000000021',
  'b1000000-0000-4000-8000-000000000007',
  'progress-earlier-past-apply',
  'Apply',
  'Past Perfect Continuous for long background before a past event.',
  'C1',
  '{"usage":"Goal: had been + V-ing when a long past effort was running before a cutoff.","forms":{"affirmative":"had been + V-ing","negative":"hadn''t been + V-ing","question":"Had + subject + been + V-ing?"},"examples":[{"id":"ex-1","context":"On-call","sentence":"The worker had been retrying for an hour when we killed it."},{"id":"ex-2","context":"Slack","sentence":"We had been draining traffic before the proxy restart."},{"id":"ex-3","context":"Standup","sentence":"I had not been watching canary when the page fired."},{"id":"ex-4","context":"PR","sentence":"She had been holding the lock when the timeout hit."},{"id":"ex-5","context":"RFC","sentence":"Two writers had been active before the unique index landed."}],"tips":["had been + V-ing = long background that stopped (or was cut) in the past.","Skip this form in daily standups unless the timeline is genuinely nested."]}'::jsonb,
  1,
  1,
  3,
  true
)
