values (
  'b2000000-0000-4000-8000-000000000022',
  'b1000000-0000-4000-8000-000000000008',
  'future-milestones-form',
  'Form',
  'will be + V-ing and will have + V-ed.',
  'B1',
  '{"usage":"Goal: form in-progress future (will be) and completed-by-then (will have).","forms":{"affirmative":"will be + V-ing  ·  will have + past participle","negative":"won''t be + V-ing  ·  won''t have + past participle","question":"Will + subject + be + V-ing?  ·  Will + subject + have + V-ed?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"I will be pairing during the 15:00 incident drill."},{"id":"ex-2","context":"Client","sentence":"We will have shipped the patch by Friday."},{"id":"ex-3","context":"Slack","sentence":"She won''t be merging during the freeze."},{"id":"ex-4","context":"PR","sentence":"Will you have finished the rollback plan by then?"},{"id":"ex-5","context":"Standup","sentence":"They will be soaking the canary this afternoon."}],"tips":["will be + V-ing, not will + V-ing.","will have + participle, not will have + yesterday."]}'::jsonb,
