values (
  'b2000000-0000-4000-8000-000000000023',
  'b1000000-0000-4000-8000-000000000008',
  'future-milestones-use',
  'Use',
  'In-progress at a future time vs done by a deadline.',
  'B2',
  '{"usage":"Goal: will be for overlap; will have for a completed milestone.","forms":{"affirmative":"will be + V-ing  ·  will have + past participle","negative":"won''t be + V-ing  ·  won''t have + past participle","question":"Will + subject + be + V-ing?  ·  Will + subject + have + V-ed?"},"examples":[{"id":"ex-1","context":"Client","sentence":"At 16:00 we will be still failing over, not celebrating."},{"id":"ex-2","context":"Standup","sentence":"By standup tomorrow we will have a decision."},{"id":"ex-3","context":"Slack","sentence":"I will be on-call, so I will not join grooming."},{"id":"ex-4","context":"PR","sentence":"The migration will have run before we open traffic."},{"id":"ex-5","context":"RFC","sentence":"We will not have dual-write complete until next week."}],"tips":["by Friday / by standup → often will have.","at 16:00 / during the drill → often will be."]}'::jsonb,
