insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000024',
  'b1000000-0000-4000-8000-000000000008',
  'future-milestones-apply',
  'Apply',
  'Future Perfect Continuous for duration up to a future checkpoint.',
  'C1',
  '{"usage":"Goal: will have been + V-ing for how long an effort will last by a milestone.","forms":{"affirmative":"will have been + V-ing","negative":"won''t have been + V-ing","question":"Will + subject + have been + V-ing?"},"examples":[{"id":"ex-1","context":"Client","sentence":"By Friday we will have been mitigating for three days."},{"id":"ex-2","context":"Standup","sentence":"At the retro we will have been dual-writing for a week."},{"id":"ex-3","context":"Slack","sentence":"I will not have been on-call long enough to swap."},{"id":"ex-4","context":"RFC","sentence":"The canary will have been soaking for two hours by cutover."},{"id":"ex-5","context":"PR","sentence":"Will we have been running the backfill that long?"}],"tips":["will have been + V-ing needs a duration and a future checkpoint.","Skip this in daily English unless a client asks how long it will have run."]}'::jsonb,
  1,
  1,
  3,
  true
)
