insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000025',
  'b1000000-0000-4000-8000-000000000009',
  'clear-sentence-building-form',
  'Form',
  'a/an/the and common verb patterns (to vs -ing).',
  'A2',
  '{"usage":"Goal: pick a/an/the and the right verb pattern in a short ticket line.","forms":{"affirmative":"a/an + first mention · the + known item · V + to/-ing","negative":"no article with general mass nouns (latency, traffic)","question":"Need to + V?  Avoid + V-ing?"},"examples":[{"id":"ex-1","context":"PR","sentence":"I added an index on the payments table."},{"id":"ex-2","context":"Slack","sentence":"The latency is still high on checkout."},{"id":"ex-3","context":"Standup","sentence":"We need to revert the flag."},{"id":"ex-4","context":"Docs","sentence":"Avoid holding the lock in the request path."},{"id":"ex-5","context":"Ticket","sentence":"Traffic dropped after the deploy."}],"tips":["a/an = first mention; the = this known thing.","need to + base; avoid + V-ing (not avoid to)."]}'::jsonb,
  1,
  1,
  1,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000026',
  'b1000000-0000-4000-8000-000000000009',
  'clear-sentence-building-use',
  'Use',
  'Connectors: because, so, however in ticket English.',
  'B1',
  '{"usage":"Goal: join cause, result, and contrast without a run-on.","forms":{"affirmative":"because + cause · so + result · however + contrast","negative":"Do not stack however so because in one breath.","question":"Why? Because… / So what is next?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"Checkout failed because the cache was stale."},{"id":"ex-2","context":"Standup","sentence":"CI is red, so I will not merge."},{"id":"ex-3","context":"PR","sentence":"The query is correct; however, it still tablescans."},{"id":"ex-4","context":"Ticket","sentence":"We rolled back so customers could check out."},{"id":"ex-5","context":"Client","sentence":"Impact is local. However, we are still investigating."}],"tips":["because = why; so = therefore; however = contrast.","however usually needs a full stop or semicolon, not a comma splice."]}'::jsonb,
  1,
  1,
  2,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
