insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000027',
  'b1000000-0000-4000-8000-000000000009',
  'clear-sentence-building-apply',
  'Apply',
  'Tight RFC English: one idea, one connector, no fluff.',
  'B2',
  '{"usage":"Goal: write a ticket sentence that a reviewer can scan.","forms":{"affirmative":"Subject + verb + because/so/which means…","negative":"which means + clause (not which mean)","question":"What does this mean for checkout?"},"examples":[{"id":"ex-1","context":"RFC","sentence":"We keep dual-write because rollback must stay cheap."},{"id":"ex-2","context":"PR","sentence":"The index is missing, which means checkout tablescans."},{"id":"ex-3","context":"Slack","sentence":"Latency is unmeasured, so this is still a hypothesis."},{"id":"ex-4","context":"Ticket","sentence":"Please avoid blocking the writer; use a queue instead."},{"id":"ex-5","context":"Client","sentence":"The workaround holds; however, we still owe a patch."}],"tips":["which means + full clause.","Prefer avoid + V-ing; \"Please avoid to block\" is a common mistake (shown as Do not)."]}'::jsonb,
  1,
  1,
  3,
  true
)
