insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000028',
  'b1000000-0000-4000-8000-000000000010',
  'passive-relative-form',
  'Form',
  'be + past participle; who/which/that for extra info.',
  'A2',
  '{"usage":"Goal: form a short passive and a relative clause.","forms":{"affirmative":"is/are/was/were + V-ed  ·  noun + who/which/that + clause","negative":"isn''t/aren''t/wasn''t + V-ed","question":"Was the flag reverted?  The job that failed…"},"examples":[{"id":"ex-1","context":"Slack","sentence":"The flag was reverted at 11:04."},{"id":"ex-2","context":"PR","sentence":"The job that failed is being retried."},{"id":"ex-3","context":"Ticket","sentence":"Customers who hit checkout saw 5xx."},{"id":"ex-4","context":"Standup","sentence":"The RFC which we opened is still in review."},{"id":"ex-5","context":"Docs","sentence":"Traffic is routed through the gateway."}],"tips":["Passive = be + participle (was reverted, not was revert).","who = people; which/that = things."]}'::jsonb,
  1,
  1,
  1,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000029',
  'b1000000-0000-4000-8000-000000000010',
  'passive-relative-use',
  'Use',
  'When passive hides the actor; when relative keeps the ticket tight.',
  'B1',
  '{"usage":"Goal: use passive for the action; name the owner only when it matters.","forms":{"affirmative":"X was deployed.  The service that owns retries…","negative":"Do not write was been deployed.","question":"Who owns it? vs What was deployed?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"Checkout was degraded for twelve minutes."},{"id":"ex-2","context":"PR","sentence":"The patch that landed last night is still soaking."},{"id":"ex-3","context":"Standup","sentence":"I reverted the flag — I own that call."},{"id":"ex-4","context":"Ticket","sentence":"The worker which writes the outbox was restarted."},{"id":"ex-5","context":"Client","sentence":"A workaround was published in the status page."}],"tips":["Passive is fine when the actor is obvious or unknown.","Switch to active when you need a named owner."]}'::jsonb,
  1,
  1,
  2,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000030',
  'b1000000-0000-4000-8000-000000000010',
  'passive-relative-apply',
  'Apply',
  'Incident register: reduced relative clauses and clean passives.',
  'B2',
  '{"usage":"Goal: write notes a secondary can scan under pressure.","forms":{"affirmative":"the job failing on lock · traffic routed via the gateway","negative":"Avoid the job which that failed.","question":"Which change was deployed? The one that…"},"examples":[{"id":"ex-1","context":"On-call","sentence":"The change deployed at 10:51 is the suspect."},{"id":"ex-2","context":"Slack","sentence":"Errors seen on checkout were tied to the stale cache."},{"id":"ex-3","context":"RFC","sentence":"Connections drained before the restart stayed healthy."},{"id":"ex-4","context":"PR","sentence":"The index added in this PR covers the filter."},{"id":"ex-5","context":"Client","sentence":"The patch shipped yesterday is still rolling out."}],"tips":["You can drop who/which/that + be: the change deployed at 10:51.","Do not stack which that in one clause."]}'::jsonb,
  1,
  1,
  3,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000031',
  'b1000000-0000-4000-8000-000000000011',
  'requests-questions-modals-form',
  'Form',
  'Modal + base verb. Cue: Can you / Could you / Should we.',
  'A2',
  '{"usage":"Goal: form a polite ask and a clear obligation.","forms":{"affirmative":"can/could/should/must + base verb","negative":"can''t / shouldn''t / must not + base","question":"Can/Could/Should + subject + base?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"Could you review this RFC today?"},{"id":"ex-2","context":"Standup","sentence":"Can you take the on-call swap?"},{"id":"ex-3","context":"PR","sentence":"We should add a rollback note."},{"id":"ex-4","context":"On-call","sentence":"We must not ship schema changes in this freeze."},{"id":"ex-5","context":"Ticket","sentence":"I can''t merge until CI is green."}],"tips":["Modal + base (could you review, not could you to review).","must not / can''t — not must to / should to."]}'::jsonb,
  1,
  1,
  1,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000032',
  'b1000000-0000-4000-8000-000000000011',
  'requests-questions-modals-use',
  'Use',
  'could = polite; should = advice; must = hard gate.',
  'B1',
  '{"usage":"Goal: match modal strength to standup, review, and incident.","forms":{"affirmative":"could you…  ·  we should…  ·  we must…","negative":"mustn''t for policy; shouldn''t for advice","question":"Should we page secondary?"},"examples":[{"id":"ex-1","context":"PR","sentence":"Could you leave a comment on the lock risk?"},{"id":"ex-2","context":"Standup","sentence":"We should slip the train if CI stays red."},{"id":"ex-3","context":"On-call","sentence":"We must page secondary on P0."},{"id":"ex-4","context":"Slack","sentence":"You might be blocked on access — can you confirm?"},{"id":"ex-5","context":"Client","sentence":"Could we move the call to 16:00?"}],"tips":["could you is softer than can you for reviews.","must is for policy and P0, not taste."]}'::jsonb,
  1,
  1,
  2,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000033',
  'b1000000-0000-4000-8000-000000000011',
  'requests-questions-modals-apply',
  'Apply',
  'Tone: requests vs orders in incidents and client threads.',
  'B2',
  '{"usage":"Goal: stay firm on safety, polite on asks, hedged on guesses.","forms":{"affirmative":"Could you…  ·  We should…  ·  This might be…","negative":"Avoid You must when a could you would land the review.","question":"Can you confirm? vs Must we declare?"},"examples":[{"id":"ex-1","context":"Slack","sentence":"This might be a cache issue — can you confirm on staging?"},{"id":"ex-2","context":"Client","sentence":"Could you share the failing request id?"},{"id":"ex-3","context":"On-call","sentence":"We must keep the flag off until error rate drops."},{"id":"ex-4","context":"PR","sentence":"You should add a metric before we ship this."},{"id":"ex-5","context":"Standup","sentence":"I can take the extra on-call hour."}],"tips":["might/may for unmeasured hypotheses.","must for safety gates; could you for information asks."]}'::jsonb,
  1,
  1,
  3,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000034',
  'b1000000-0000-4000-8000-000000000012',
  'conditions-reporting-tone-form',
  'Form',
  'If + present, will… and told/said reporting.',
  'A2',
  '{"usage":"Goal: form a real condition and a short reported line.","forms":{"affirmative":"If + present, will + V  ·  X told me (that) + clause","negative":"If CI isn''t green, we won''t merge.","question":"What did she say? She said the flag was off."},"examples":[{"id":"ex-1","context":"Standup","sentence":"If CI stays green, we will ship today."},{"id":"ex-2","context":"Slack","sentence":"She told me the flag was already off."},{"id":"ex-3","context":"PR","sentence":"He said the tests were flaky."},{"id":"ex-4","context":"Client","sentence":"If we don''t get a request id, we cannot reproduce."},{"id":"ex-5","context":"Ticket","sentence":"I told the channel we were rolling back."}],"tips":["If + present, will + base (not if will).","told + person; said + clause (not said me)."]}'::jsonb,
  1,
  1,
  1,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000035',
  'b1000000-0000-4000-8000-000000000012',
  'conditions-reporting-tone-use',
  'Use',
  'Real vs hypothetical; backshift in reports.',
  'B1',
  '{"usage":"Goal: choose if/will vs if/would; backshift when the report is later.","forms":{"affirmative":"If we ship now, we will…  ·  If we shipped now, we would…","negative":"She said she was blocked (not she is, if the report is later).","question":"What would we do if CI stayed red?"},"examples":[{"id":"ex-1","context":"Standup","sentence":"If we merge now, we will miss the freeze."},{"id":"ex-2","context":"RFC","sentence":"If we merged without dual-write, we would lose rollback."},{"id":"ex-3","context":"Slack","sentence":"She said she was blocked on access."},{"id":"ex-4","context":"Client","sentence":"They asked if we could move the window."},{"id":"ex-5","context":"PR","sentence":"He told me the tests had failed twice."}],"tips":["Real next step → if + present, will.","Hypothetical / advice → if + past, would."]}'::jsonb,
  1,
  1,
  2,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
  content = excluded.content,
  content_schema_version = excluded.content_schema_version,
  content_revision = excluded.content_revision,
  sort_order = excluded.sort_order,
  published = excluded.published,
  updated_at = now();

insert into public.grammar_lessons (
  id, topic_id, slug, title, description, level, content, content_schema_version, content_revision, sort_order, published
)
values (
  'b2000000-0000-4000-8000-000000000036',
  'b1000000-0000-4000-8000-000000000012',
  'conditions-reporting-tone-apply',
  'Apply',
  'Client tone: hedge, report, and condition without over-promising.',
  'B2',
  '{"usage":"Goal: report status with if/will, hedges, and clear owners.","forms":{"affirmative":"If X holds, we will…  ·  They asked us to…  ·  This seems…","negative":"Avoid We will have fixed it yesterday in a client mail.","question":"Could you confirm if the workaround still holds?"},"examples":[{"id":"ex-1","context":"Client","sentence":"If the workaround holds, we will keep it overnight."},{"id":"ex-2","context":"Slack","sentence":"They asked us to confirm the request id."},{"id":"ex-3","context":"Standup","sentence":"This seems like a cache issue, not a code change."},{"id":"ex-4","context":"PR","sentence":"He said the rollback had already been tested."},{"id":"ex-5","context":"Client","sentence":"We would delay cutover if error rate stays high."}],"tips":["seems/appears/might keep you honest when RCA is open.","would + delay for a conditional plan, not a fake promise."]}'::jsonb,
  1,
  1,
  3,
  true
)
on conflict (topic_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  level = excluded.level,
